#define main prior_kernel_main
#include "../round2/kernel.cpp"
#undef main
void reference(std::shared_ptr<a2::Index> idx,std::vector<std::pair<z3::expr,bool>> const& atoms){auto q=std::make_shared<a2::r4::QueryPreferences>();q->policy=a2::r4::Policy::Reference;for(auto const& p:atoms)q->reference[a2::HostView{}.identity(p.first)]=p.second;idx->version=1;idx->preferences=q;}
int main(){try{J tests=J::array();
 {z3::context c;auto a=c.bool_const("a"),b=c.bool_const("b");auto f=(a||b)&&(a||!b)&&(!a||b);z3::solver s(c);s.set("phase_selection",1u);s.push();s.add(f);auto idx=std::make_shared<a2::Index>();reference(idx,{{a,false},{b,false}});install(s,idx);check(s.check()==z3::sat,"reference backtracking lost SAT");auto st=stats(s);check(s.get_model().eval(f,true).is_true(),"illegal backtracking");bool popped=false;for(auto const& action:st["actions"])popped|=action["phase_changed"].get<bool>()&&action["trailed_assignment_popped"].get<bool>();check(popped,"soft reference never abandoned");clear(s);check(idx->active==0,"reference active leak");s.pop();s.reset();s.add(a);check(s.check()==z3::sat&&stats(s).empty(),"reference survived clear/reset");s.set("rlimit",1u);install(s,idx);check(s.check()==z3::unknown,"native cancellation not exercised");clear(s);s.set("rlimit",0u);check(s.check()==z3::sat,"cancellation poisoned reuse");tests.push_back({{"test","reference_backtrack_reset_cancel"},{"stats",st}});}
 {z3::context c;auto p=c.bool_const("p"),q=c.bool_const("q");z3::tactic ts[2]={z3::tactic(c,"smt"),z3::tactic(c,"smt")};auto s=z3::par_or(2,ts).mk_solver();s.add(p||q);auto idx=std::make_shared<a2::Index>();reference(idx,{{p,true},{q,true}});install(s,idx);check(s.check()==z3::sat,"translated reference SAT");auto st=stats(s);check(st["phase_overrides"].get<unsigned>()>0,"reference failed translated goal");clear(s);check(idx->active==0,"translated reference leak");tests.push_back({{"test","reference_cross_manager"},{"stats",st}});}
 {z3::context c;z3::solver s(c);s.set("timeout",2000u);s.set("phase_selection",0u);s.push();unsigned n=12,m=11;std::vector<std::vector<z3::expr>> ps;std::vector<std::pair<z3::expr,bool>> atoms;
  for(unsigned i=0;i<n;++i){ps.emplace_back();z3::expr_vector row(c);for(unsigned j=0;j<m;++j){auto v=c.bool_const(("h_"+std::to_string(i)+"_"+std::to_string(j)).c_str());ps.back().push_back(v);row.push_back(v);atoms.emplace_back(v,true);}s.add(z3::mk_or(row));}for(unsigned j=0;j<m;++j)for(unsigned i=0;i<n;++i)for(unsigned k=i+1;k<n;++k)s.add(!ps[i][j]||!ps[k][j]);auto idx=std::make_shared<a2::Index>();reference(idx,atoms);install(s,idx,2,0.2);auto r=s.check();auto st=stats(s);check(st["phase_overrides"].get<unsigned>()>0,"reference exposure unexercised");check(r==z3::unknown&&st["exposure_limit"].get<bool>()&&s.reason_unknown()=="guidance_exposure_limit","reference exposure not protected");check(st["suggestions"]==0,"reference spent coverage quota");clear(s);s.pop();auto x=c.int_const("x");s.add(x==3);check(s.check()==z3::sat,"reference exposure reuse");
  z3::params cfg(c);cfg.set("ls_sampling",true);cfg.set("auto_config",false);cfg.set("logic","QF_LIA");auto ls=z3::with(z3::tactic(c,"smt"),cfg).mk_solver();ls.add(x==3);install(ls,idx);check(ls.check()==z3::sat,"CCSS isolation SAT");auto lst=stats(ls);clear(ls);check(lst["actions"].empty(),"reference leaked into CCSS");tests.push_back({{"test","reference_exposure_and_CCSS_rejection"},{"stats",st},{"CCSS",lst}});
 }
 std::cout<<J({{"passed",true},{"tests",tests}}).dump(2)<<'\n';
 }catch(std::exception const& e){std::cerr<<e.what()<<'\n';return 1;}}
